KEYS = ["slug","continent","category","fame","lat","lng","start","end","rule","name_fr","name_en","place","country_fr","country_en","desc_fr","desc_en","photos","youtube","source","featured"]

def main(out):
    os.makedirs(out, exist_ok=True)
    seen = set()
    for row in F:
        d = dict(zip(KEYS, row))
        d.update(FIX.get(d["slug"], {}))
        assert d["slug"] not in seen, d["slug"]; seen.add(d["slug"])
        doc = {
          "slug": d["slug"], "continent": d["continent"], "category": d["category"], "fame": d["fame"],
          "geo": {"lat": d["lat"], "lng": d["lng"]},
          "place": d["place"], "country": {"fr": d["country_fr"], "en": d["country_en"]},
          "dates": [{"year": 2026, "start": d["start"], "end": d["end"]}],
          "rule": d["rule"],
          "name": {"fr": d["name_fr"], "en": d["name_en"]},
          "description": {"fr": d["desc_fr"], "en": d["desc_en"]},
          "translations_machine": [],
          "photos": [{"file": f, "caption": {"fr": c}, "role": r, "license": "voir la page Commons"} for f, c, r in d["photos"]],
          "videos": [{"id": v} for v in d["youtube"]],
          "sources": [d["source"]],
          "featured": d["featured"],
          "added": "2026-11-08", "updated": "2026-11-08", "by": "import Fêtes du monde"
        }
        with open(os.path.join(out, d["slug"] + ".json"), "w", encoding="utf-8") as fh:
            json.dump(doc, fh, ensure_ascii=False, indent=2)
    print(len(seen), "fêtes")

if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "content/fetes")
